window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-40c06d4071119f34"]={"versions": [{"id": "FIG-40c06d4071119f34", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Funktions- und Domänen-Architekturdiagramm (Software Composition & Component Interaction Overview) auf Ebene der AUTOSAR-Applikationsschicht (Application Layer / VFB-Ebene).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert die modulare Dekomposition der AUTOSAR-Chassis-Domäne gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3).</li>\n<li>Definiert die hierarchischen Signal- und Kontrollbeziehungen zwischen Umfeld-/Fahrzeugsensorik, High-Level-Assistenz- und Regelfunktionen (ACC, VLC, SSM), Querstabilisierungs-SWCs und den Basis-Aktuatorsystemen.</li>\n<li>Markiert die Domänengrenze zur Antriebs-Domäne (<code>Power-Train</code>, grau hinterlegt als externes Subsystem), welche die Längskraft-Schnittstelle bedient.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Sensor-Ebene (Perzeptionsschicht)</p>\n<ul class=\"fig-list\">\n<li><strong><code>SurrndgsSnsr</code> (Surroundings Sensor):</strong> Sensor-SWC/Composition für Umfeldsensorik (Radar, Lidar, Kamera) zur Erfassung von Objektabständen, Relativgeschwindigkeiten und Spurgeometrien.</li>\n<li><strong><code>ChassisSnsr</code> (Chassis Sensor):</strong> Sensor-SWC/Composition für fahrzeugeigene Fahrdynamikgrößen (Raddrehzahlen, Gierrate, Quer-/Längsbeschleunigung, Lenkwinkel).</li>\n</ul>\n<p class=\"fig-p\">#### Koordinations- & Reglerebene (High-Level Control)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> (Cruise Control & Adaptive Cruise Control):</strong> Berechnet aus Fahrerwunsch und Umfelddaten longitudinale Soll-Bewegungsgrößen ($v_{set}$, $a_{req}$).</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control):</strong> Zentraler Längsdynamikkoordinator. Arbitriert Beschleunigungsanforderungen (Fahrerpedal, ACC, Limiter) und verteilt Sollmomente an Vortrieb (<code>Power-Train</code>) und Verzögerung (<code>Esc</code>).</li>\n<li><strong><code>Ssm</code> (Standstill Management):</strong> Zustandsmanager für Fahrzeugstillstand (Hill-Hold, Stop&Go, Schnittstelle hydraulischer Halt $\\leftrightarrow$ elektromechanische Verriegelung).</li>\n<li><strong><code>Rsc</code> (Roll Stability Control):</strong> Kipp- und Wankstabilitätsüberwachung; fordert stabilisierende Radbremsungen bei <code>Esc</code> an.</li>\n<li><strong><code>SteerVehStabyCtrl</code> (Steering Vehicle Stability Control):</strong> Fahrdynamische Lenkungsstabilisierung (z. B. Übersteuer-/Untersteuer-Korrektur, Gegenlenkempfehlung / DSR).</li>\n<li><strong><code>SteerDrvrAsscSys</code> (Steering Driver Assistance System):</strong> Komfort- und Spurführungsassistenten (LKA, Parklenkassistent).</li>\n</ul>\n<p class=\"fig-p\">#### Aktuator- & Basisebene (Low-Level Execution & Subsysteme)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power-Train</code> (Powertrain, grau):</strong> Externe Domäne für Bereitstellung und Modulation des Antriebsmoments.</li>\n<li><strong><code>TirePMon</code> (Tire Pressure Monitoring):</strong> Reifendrucküberwachung (direkt/indirekt).</li>\n<li><strong><code>Epb</code> (Electric Parking Brake):</strong> Elektromechanischer Feststellbremsaktuator.</li>\n<li><strong><code>Esc</code> (Electronic Stability Control):</strong> Bremssystemregler (ABS, ASR, ESP, aktiver hydraulischer Bremsdruckaufbau).</li>\n<li><strong><code>Steer</code> (Steering):</strong> Lenksystem-Basisansteuerung (EPS / Überlagerungslenkung).</li>\n<li><strong><code>Susp</code> (Suspension):</strong> Vertikaldynamikregelung (adaptive Dämpfung, Niveauregulierung).</li>\n<li><strong><code>DtTqDibtn</code> (Drivetrain Torque Distribution):</strong> Drehmomentverteilung (Allrad-Längs-/Quersperren, Torque Vectoring).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> $\\leftrightarrow$ <code>Vlc</code>:</strong> Bidirektionales Sender-Receiver-Interface (<code>AccelReq</code>, Status/Availability).</li>\n<li><strong><code>Vlc</code> $\\rightarrow$ <code>Power-Train</code>:</strong> Unidirektionaler Befehlspfad für positives Drehmoment/Beschleunigung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Bidirektionaler Pfad für Bremsverzögerungsanforderung und Status/Grenzmoment-Rückmeldung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Ssm</code> $\\leftrightarrow$ <code>Epb</code> / <code>Esc</code>:</strong> Stillstandskaskade. <code>Ssm</code> steuert hydraulische Haltefunktion (<code>Esc</code>) und Parkbremsen-Verriegelung (<code>Epb</code>).</li>\n<li><strong>Stabilitäts-Kopplungsbus (Verzweigungspunkt über <code>Esc</code>):</strong></li>\n<li>Signalisierung von Instabilitäten/Eingriffen an <code>CrsCtrlAndAcc</code> (ACC-Deaktivierung/Inhibit).</li>\n<li>Koordination von Radbremseingriffen (<code>Esc</code>) mit Lenkeingriffen (<code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code>).</li>\n<li><strong><code>SteerVehStabyCtrl</code> / <code>SteerDrvrAsscSys</code> $\\leftrightarrow$ <code>Steer</code>:</strong> Vorgabe von Zusatzlenkmomenten bzw. Zusatzlenkwinkeln an die Servolenkung.</li>\n<li><strong>Unterer Querkopplungs-Bus:</strong> Gemeinsame Systemstatuslinie der Basisaktuatoren für globale Betriebsmodi (Fahrzeugzustand, Klemmenstatus, aggregierte Radgeschwindigkeiten/Schlupfzustände).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Längsdynamischer Regel- und Halteablauf (ACC bis Stop & Hold)</p>\n<ol class=\"fig-list\">\n<li><strong>Sollwertgenerierung:</strong> <code>SurrndgsSnsr</code> liefert Target-Daten $\\rightarrow$ <code>CrsCtrlAndAcc</code> ermittelt Sollverzögerung $a_{req} < 0$.</li>\n<li><strong>Arbitrierung & Verteilung:</strong> <code>Vlc</code> moduliert <code>Power-Train</code>-Moment auf Leerlauf/Schub und übergibt die Verzögerungsanforderung an <code>Esc</code>.</li>\n<li><strong>Verzögerung:</strong> <code>Esc</code> regelt den Bremsdruck ein, bis Fahrzeugstillstand ($v \\approx 0$) detektiert wird.</li>\n<li><strong>Stillstandsübergabe (Standstill Handshake):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Vlc</code> meldet Stillstandsanforderung an <code>Ssm</code>.</li>\n<li><code>Ssm</code> hält das Fahrzeug zunächst aktiv über die Hydraulikventile des <code>Esc</code> (Hydraulic Hold).</li>\n<li>Bei längerem Stillstand, Timeout oder Systemabschaltung kommandiert <code>Ssm</code> das Zuziehen der <code>Epb</code>.</li>\n<li>Nach Quittierung des mechanischen Kraftschlusses durch <code>Epb</code> baut <code>Esc</code> den hydraulischen Druck ab.</li>\n</ul>\n<p class=\"fig-p\">#### Stabilitäts-Intervention & Override</p>\n<ol class=\"fig-list\">\n<li><strong>Instabilitätserkennung:</strong> <code>ChassisSnsr</code> meldet Gierratenabweichung $\\rightarrow$ <code>Esc</code> löst radselektive Bremsung aus.</li>\n<li><strong>Inhibit:</strong> Über den Verzweigungsknoten wird <code>CrsCtrlAndAcc</code> instantan degradiert/deaktiviert (Ausschuss von Reglerkonflikten).</li>\n<li><strong>Kooperative Stabilisierung:</strong> Parallel kommuniziert <code>Esc</code> mit <code>SteerVehStabyCtrl</code>, um über <code>Steer</code> ein gegenlenkendes Moment einzusteuern.</li>\n<li><strong>Kippschutz:</strong> Erkennt <code>Rsc</code> kritische Wankbewegungen, erzwingt es prioritäre Notbremskommandos an <code>Esc</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C-Kapselung & Schichtung:</strong></li>\n<li>Strenges Einhalten des Schichtenprinzips: Assistenz-SWCs (<code>CrsCtrlAndAcc</code>) dürfen keine direkten Aktuatorports (<code>Esc</code>, <code>Power-Train</code>, <code>Epb</code>) bedienen; sämtliche Eingriffe müssen über Koordinatoren (<code>Vlc</code>, <code>Ssm</code>) arbitriert werden.</li>\n<li>Zeitkritische Pfade (<code>Vlc</code> $\\leftrightarrow$ <code>Esc</code> $\\leftrightarrow$ <code>Power-Train</code>) erfordern RTE-Task-Perioden $\\le 10\\,\\text{ms}$ mit synchronem Lese-/Schreibzugriff (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) zur Vermeidung von Jitter und Semaphore-Blocking.</li>\n<li><strong>Port-Definition & Standard-Datentypen:</strong></li>\n<li>Verwendung der genormten AUTOSAR-Application-Interface-Datentypen (z. B. Beschleunigungen in $\\text{m/s}^2$, Momente in $\\text{Nm}$, Drehzahlen in $1/\\text{min}$ nach standardisierten <code>CompuMethods</code>).</li>\n<li>Signal-Statusflags müssen Signalqualitäten (<code>Valid</code>, <code>Invalid</code>, <code>Degraded</code>) mitführen, um deterministische Rückfallebenen bei Sensorausfall abzusichern.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Kernkomponenten (<code>Vlc</code>, <code>Esc</code>, <code>Steer</code>, <code>Ssm</code>) sind typischerweise bis ASIL D eingestuft.</li>\n<li>Der Kommunikationspfad zwischen den ECUs/Partitionen erfordert E2E-Absicherung (CRC, Sequence Counter, Alive Supervision via E2E-Protection-Wrapper).</li>\n<li>Plausibilisierungs- und Degradationsgatter in <code>Vlc</code> und <code>Esc</code> sind obligatorisch, um ungewollte Beschleunigungs- oder Bremsanforderungen (z. B. durch Single-Point-Faults in ACC oder Umfeldsensorik) sicher abzufangen.</li>\n</ul>"}, {"id": "FIG-92922157b4aef669", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Funktions- und Domänen-Architekturdiagramm (Software Composition & Component Interaction Overview) auf Ebene der AUTOSAR-Applikationsschicht (Application Layer / VFB-Ebene).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert die modulare Dekomposition der AUTOSAR-Chassis-Domäne gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3).</li>\n<li>Definiert die hierarchischen Signal- und Kontrollbeziehungen zwischen Umfeld-/Fahrzeugsensorik, High-Level-Assistenz- und Regelfunktionen (ACC, VLC, SSM), Querstabilisierungs-SWCs und den Basis-Aktuatorsystemen.</li>\n<li>Markiert die Domänengrenze zur Antriebs-Domäne (<code>Power-Train</code>, grau hinterlegt als externes Subsystem), welche die Längskraft-Schnittstelle bedient.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Sensor-Ebene (Perzeptionsschicht)</p>\n<ul class=\"fig-list\">\n<li><strong><code>SurrndgsSnsr</code> (Surroundings Sensor):</strong> Sensor-SWC/Composition für Umfeldsensorik (Radar, Lidar, Kamera) zur Erfassung von Objektabständen, Relativgeschwindigkeiten und Spurgeometrien.</li>\n<li><strong><code>ChassisSnsr</code> (Chassis Sensor):</strong> Sensor-SWC/Composition für fahrzeugeigene Fahrdynamikgrößen (Raddrehzahlen, Gierrate, Quer-/Längsbeschleunigung, Lenkwinkel).</li>\n</ul>\n<p class=\"fig-p\">#### Koordinations- & Reglerebene (High-Level Control)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> (Cruise Control & Adaptive Cruise Control):</strong> Berechnet aus Fahrerwunsch und Umfelddaten longitudinale Soll-Bewegungsgrößen ($v_{set}$, $a_{req}$).</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control):</strong> Zentraler Längsdynamikkoordinator. Arbitriert Beschleunigungsanforderungen (Fahrerpedal, ACC, Limiter) und verteilt Sollmomente an Vortrieb (<code>Power-Train</code>) und Verzögerung (<code>Esc</code>).</li>\n<li><strong><code>Ssm</code> (Standstill Management):</strong> Zustandsmanager für Fahrzeugstillstand (Hill-Hold, Stop&Go, Schnittstelle hydraulischer Halt $\\leftrightarrow$ elektromechanische Verriegelung).</li>\n<li><strong><code>Rsc</code> (Roll Stability Control):</strong> Kipp- und Wankstabilitätsüberwachung; fordert stabilisierende Radbremsungen bei <code>Esc</code> an.</li>\n<li><strong><code>SteerVehStabyCtrl</code> (Steering Vehicle Stability Control):</strong> Fahrdynamische Lenkungsstabilisierung (z. B. Übersteuer-/Untersteuer-Korrektur, Gegenlenkempfehlung / DSR).</li>\n<li><strong><code>SteerDrvrAsscSys</code> (Steering Driver Assistance System):</strong> Komfort- und Spurführungsassistenten (LKA, Parklenkassistent).</li>\n</ul>\n<p class=\"fig-p\">#### Aktuator- & Basisebene (Low-Level Execution & Subsysteme)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power-Train</code> (Powertrain, grau):</strong> Externe Domäne für Bereitstellung und Modulation des Antriebsmoments.</li>\n<li><strong><code>TirePMon</code> (Tire Pressure Monitoring):</strong> Reifendrucküberwachung (direkt/indirekt).</li>\n<li><strong><code>Epb</code> (Electric Parking Brake):</strong> Elektromechanischer Feststellbremsaktuator.</li>\n<li><strong><code>Esc</code> (Electronic Stability Control):</strong> Bremssystemregler (ABS, ASR, ESP, aktiver hydraulischer Bremsdruckaufbau).</li>\n<li><strong><code>Steer</code> (Steering):</strong> Lenksystem-Basisansteuerung (EPS / Überlagerungslenkung).</li>\n<li><strong><code>Susp</code> (Suspension):</strong> Vertikaldynamikregelung (adaptive Dämpfung, Niveauregulierung).</li>\n<li><strong><code>DtTqDistbn</code> (Drivetrain Torque Distribution):</strong> Drehmomentverteilung (Allrad-Längs-/Quersperren, Torque Vectoring).</li>\n<li><strong><code>PrkgAid</code> (Parking Aid):</strong> Parkassistenz-Subsystem zur Unterstützung bei Rangiervorgängen und Parkmanövern.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> $\\leftrightarrow$ <code>Vlc</code>:</strong> Bidirektionales Sender-Receiver-Interface (<code>AccelReq</code>, Status/Availability).</li>\n<li><strong><code>Vlc</code> $\\rightarrow$ <code>Power-Train</code>:</strong> Unidirektionaler Befehlspfad für positives Drehmoment/Beschleunigung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Bidirektionaler Pfad für Bremsverzögerungsanforderung und Status/Grenzmoment-Rückmeldung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Ssm</code> $\\leftrightarrow$ <code>Epb</code> / <code>Esc</code>:</strong> Stillstandskoordination (Anforderung Haltezustand an <code>Ssm</code>, hydraulische Bremsdruckhaltung via <code>Esc</code>, Übergang zur mechanischen Verriegelung via <code>Epb</code>).</li>\n<li><strong><code>Rsc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Vertikaler Stabilisierungspfad (Kippgefahr-Erkennung und Bremseingriffsanforderung).</li>\n<li><strong><code>SteerVehStabyCtrl</code> / <code>SteerDrvrAsscSys</code> $\\rightarrow$ <code>Steer</code>:</strong> Unidirektionale Ansteuerpfade für fahrdynamische bzw. assistierende Überlagerungslenkeingriffe.</li>\n<li><strong><code>Esc</code> $\\rightarrow$ <code>CrsCtrlAndAcc</code>, <code>Vlc</code>, <code>SteerVehStabyCtrl</code>, <code>SteerDrvrAsscSys</code>:</strong> Bereitstellung von Raddrehzahlen und Fahrzeugbewegungszuständen über Abzweigknoten.</li>\n<li><strong>Untere Verteilleitung (von <code>Esc</code>):</strong> Verteilung zentraler Raddynamikgrößen an <code>TirePMon</code>, <code>Epb</code>, <code>Steer</code>, <code>Susp</code>, <code>DtTqDistbn</code> sowie die neu angebundene Komponente <code>PrkgAid</code> und Kopplungspfad zu <code>Power-Train</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamische Wirkkette:</strong> Fahrer- oder ACC-Vorgaben werden in <code>CrsCtrlAndAcc</code> generiert und an <code>Vlc</code> übermittelt. <code>Vlc</code> führt die Priorisierung/Arbitrierung durch und adressiert bei Beschleunigungsbedarf das externe <code>Power-Train</code>-System, bei Verzögerungsbedarf das <code>Esc</code>. Im Stillstandsfall übernimmt <code>Ssm</code> die Kaskadierung vom hydraulischen Halten (<code>Esc</code>) zum dauerhaften Feststellen (<code>Epb</code>).</li>\n<li><strong>Querdynamische Wirkkette:</strong> <code>SteerVehStabyCtrl</code> (stabilitätsrelevant) und <code>SteerDrvrAsscSys</code> (komfortrelevant) senden unabhängige Überlagerungs- bzw. Lenkmomentanforderungen an das Basislenksystem <code>Steer</code>. Bei kritischen Wankbewegungen triggert <code>Rsc</code> autonome Stabilisierungsbremsungen über <code>Esc</code>.</li>\n<li><strong>Zustands- und Datenrückkopplung:</strong> <code>Esc</code> fungiert als primärer Sensor-/Fahrdynamik-Hub, der gemessene Radgeschwindigkeiten und Bewegungsgrößen sowohl an die High-Level-Funktionen (<code>CrsCtrlAndAcc</code>, <code>Vlc</code>, Lenkregler) als auch über die untere Verteilleitung an periphere Subsysteme (<code>TirePMon</code>, <code>Susp</code>, <code>DtTqDistbn</code>, <code>Steer</code>, <code>Epb</code> sowie <code>PrkgAid</code> für Wegstrecken-/Richtungserfassung) rückspeist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C-Kapselung & Schichtung:</strong></li>\n<li>Strenges Einhalten des Schichtenprinzips: Assistenz-SWCs (<code>CrsCtrlAndAcc</code>) dürfen keine direkten Aktuatorports (<code>Esc</code>, <code>Power-Train</code>, <code>Epb</code>) bedienen; sämtliche Eingriffe müssen über Koordinatoren (<code>Vlc</code>, <code>Ssm</code>) arbitriert werden.</li>\n<li>Zeitkritische Pfade (<code>Vlc</code> $\\leftrightarrow$ <code>Esc</code> $\\leftrightarrow$ <code>Power-Train</code>) erfordern RTE-Task-Perioden $\\le 10\\,\\text{ms}$ mit synchronem Lese-/Schreibzugriff (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) zur Vermeidung von Jitter und Semaphore-Blocking.</li>\n<li><strong>Port-Definition & Standard-Datentypen:</strong></li>\n<li>Verwendung der genormten AUTOSAR-Application-Interface-Datentypen (z. B. Beschleunigungen in $\\text{m/s}^2$, Momente in $\\text{Nm}$, Drehzahlen in $1/\\text{min}$ nach standardisierten <code>CompuMethods</code>).</li>\n<li>Signal-Statusflags müssen Signalqualitäten (<code>Valid</code>, <code>Invalid</code>, <code>Degraded</code>) mitführen, um deterministische Rückfallebenen bei Sensorausfall abzusichern.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Kernkomponenten (<code>Vlc</code>, <code>Esc</code>, <code>Steer</code>, <code>Ssm</code>) sind typischerweise bis ASIL D eingestuft.</li>\n<li>Der Kommunikationspfad zwischen den ECUs/Partitionen erfordert E2E-Absicherung (CRC, Sequence Counter, Alive Supervision via E2E-Protection-Wrapper).</li>\n<li>Plausibilisierungs- und Degradationsgatter in <code>Vlc</code> und <code>Esc</code> sind obligatorisch, um ungewollte Beschleunigungs- oder Bremsanforderungen (z. B. durch Single-Point-Faults in ACC oder Umfeldsensorik) sicher abzufangen.</li>\n</ul>"}, {"id": "FIG-18cf62325dc5cccf", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Funktions- und Domänen-Architekturdiagramm (Software Composition & Component Interaction Overview) auf Ebene der AUTOSAR-Applikationsschicht (Application Layer / VFB-Ebene).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert die modulare Dekomposition der AUTOSAR-Chassis-Domäne gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3).</li>\n<li>Definiert die hierarchischen Signal- und Kontrollbeziehungen zwischen Umfeld-/Fahrzeugsensorik, High-Level-Assistenz- und Regelfunktionen (ACC, VLC, SSM), Querstabilisierungs-SWCs und den Basis-Aktuatorsystemen.</li>\n<li>Markiert die Domänengrenze zur Antriebs-Domäne (<code>Power-Train</code>, grau hinterlegt als externes Subsystem), welche die Längskraft-Schnittstelle bedient.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Sensor-Ebene (Perzeptionsschicht)</p>\n<ul class=\"fig-list\">\n<li><strong><code>SurrndgsSnsr</code> (Surroundings Sensor):</strong> Sensor-SWC/Composition für Umfeldsensorik (Radar, Lidar, Kamera) zur Erfassung von Objektabständen, Relativgeschwindigkeiten und Spurgeometrien.</li>\n<li><strong><code>ChassisSnsr</code> (Chassis Sensor):</strong> Sensor-SWC/Composition für fahrzeugeigene Fahrdynamikgrößen (Raddrehzahlen, Gierrate, Quer-/Längsbeschleunigung, Lenkwinkel).</li>\n</ul>\n<p class=\"fig-p\">#### Koordinations- & Reglerebene (High-Level Control)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> (Cruise Control & Adaptive Cruise Control):</strong> Berechnet aus Fahrerwunsch und Umfelddaten longitudinale Soll-Bewegungsgrößen ($v_{set}$, $a_{req}$).</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control):</strong> Zentraler Längsdynamikkoordinator. Arbitriert Beschleunigungsanforderungen (Fahrerpedal, ACC, Limiter) und verteilt Sollmomente an Vortrieb (<code>Power-Train</code>) und Verzögerung (<code>Esc</code>).</li>\n<li><strong><code>Ssm</code> (Standstill Management):</strong> Zustandsmanager für Fahrzeugstillstand (Hill-Hold, Stop&Go, Schnittstelle hydraulischer Halt $\\leftrightarrow$ elektromechanische Verriegelung).</li>\n<li><strong><code>Rsc</code> (Roll Stability Control):</strong> Kipp- und Wankstabilitätsüberwachung; fordert stabilisierende Radbremsungen bei <code>Esc</code> an.</li>\n<li><strong><code>SteerVehStabyCtrl</code> (Steering Vehicle Stability Control):</strong> Fahrdynamische Lenkungsstabilisierung (z. B. Übersteuer-/Untersteuer-Korrektur, Gegenlenkempfehlung / DSR).</li>\n<li><strong><code>SteerDrvrAsscSys</code> (Steering Driver Assistance System):</strong> Komfort- und Spurführungsassistenten (LKA, Parklenkassistent).</li>\n</ul>\n<p class=\"fig-p\">#### Aktuator- & Basisebene (Low-Level Execution & Subsysteme)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power-Train</code> (Powertrain, grau):</strong> Externe Domäne für Bereitstellung und Modulation des Antriebsmoments.</li>\n<li><strong><code>TirePMon</code> (Tire Pressure Monitoring):</strong> Reifendrucküberwachung (direkt/indirekt).</li>\n<li><strong><code>Epb</code> (Electric Parking Brake):</strong> Elektromechanischer Feststellbremsaktuator.</li>\n<li><strong><code>Esc</code> (Electronic Stability Control):</strong> Bremssystemregler (ABS, ASR, ESP, aktiver hydraulischer Bremsdruckaufbau).</li>\n<li><strong><code>Steer</code> (Steering):</strong> Lenksystem-Basisansteuerung (EPS / Überlagerungslenkung).</li>\n<li><strong><code>Susp</code> (Suspension):</strong> Vertikaldynamikregelung (adaptive Dämpfung, Niveauregulierung).</li>\n<li><strong><code>DtTqDistbn</code> (Drivetrain Torque Distribution):</strong> Drehmomentverteilung (Allrad-Längs-/Quersperren, Torque Vectoring).</li>\n<li><strong><code>PrkgAid</code> (Parking Aid):</strong> Parkassistenz-Subsystem zur Unterstützung bei Rangiervorgängen und Parkmanövern.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> $\\leftrightarrow$ <code>Vlc</code>:</strong> Bidirektionales Sender-Receiver-Interface (<code>AccelReq</code>, Status/Availability).</li>\n<li><strong><code>Vlc</code> $\\rightarrow$ <code>Power-Train</code>:</strong> Unidirektionaler Befehlspfad für positives Drehmoment/Beschleunigung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Bidirektionaler Pfad für Bremsverzögerungsanforderung und Status/Grenzmoment-Rückmeldung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Ssm</code> $\\leftrightarrow$ <code>Epb</code> / <code>Esc</code>:</strong> Stillstandskoordination (Anforderung Haltezustand an <code>Ssm</code>, hydraulische Bremsdruckhaltung via <code>Esc</code>, Übergang zur mechanischen Verriegelung via <code>Epb</code>).</li>\n<li><strong><code>Rsc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Vertikaler Stabilisierungspfad (Kippgefahr-Erkennung und Bremseingriffsanforderung).</li>\n<li><strong><code>SteerVehStabyCtrl</code> / <code>SteerDrvrAsscSys</code> $\\rightarrow$ <code>Steer</code>:</strong> Unidirektionale Ansteuerpfade für fahrdynamische bzw. assistierende Überlagerungslenkeingriffe.</li>\n<li><strong><code>Esc</code> $\\rightarrow$ <code>CrsCtrlAndAcc</code>, <code>Vlc</code>, <code>SteerVehStabyCtrl</code>, <code>SteerDrvrAsscSys</code>:</strong> Bereitstellung von Raddrehzahlen und Fahrzeugbewegungszuständen über Abzweigknoten.</li>\n<li><strong>Untere Verteilleitung (von <code>Esc</code>):</strong> Verteilung zentraler Raddynamikgrößen an <code>TirePMon</code>, <code>Epb</code>, <code>Steer</code>, <code>Susp</code>, <code>DtTqDistbn</code> sowie die neu angebundene Komponente <code>PrkgAid</code> und Kopplungspfad zu <code>Power-Train</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamische Wirkkette:</strong> Fahrer- oder ACC-Vorgaben werden in <code>CrsCtrlAndAcc</code> generiert und an <code>Vlc</code> übermittelt. <code>Vlc</code> führt die Priorisierung/Arbitrierung durch und adressiert bei Beschleunigungsbedarf das externe <code>Power-Train</code>-System, bei Verzögerungsbedarf das <code>Esc</code>. Im Stillstandsfall übernimmt <code>Ssm</code> die Kaskadierung vom hydraulischen Halten (<code>Esc</code>) zum dauerhaften Feststellen (<code>Epb</code>).</li>\n<li><strong>Querdynamische Wirkkette:</strong> <code>SteerVehStabyCtrl</code> (stabilitätsrelevant) und <code>SteerDrvrAsscSys</code> (komfortrelevant) senden unabhängige Überlagerungs- bzw. Lenkmomentanforderungen an das Basislenksystem <code>Steer</code>. Bei kritischen Wankbewegungen triggert <code>Rsc</code> autonome Stabilisierungsbremsungen über <code>Esc</code>.</li>\n<li><strong>Zustands- und Datenrückkopplung:</strong> <code>Esc</code> fungiert als primärer Sensor-/Fahrdynamik-Hub, der gemessene Radgeschwindigkeiten und Bewegungsgrößen sowohl an die High-Level-Funktionen (<code>CrsCtrlAndAcc</code>, <code>Vlc</code>, Lenkregler) als auch über die untere Verteilleitung an periphere Subsysteme (<code>TirePMon</code>, <code>Susp</code>, <code>DtTqDistbn</code>, <code>Steer</code>, <code>Epb</code> sowie <code>PrkgAid</code> für Wegstrecken-/Richtungserfassung) rückspeist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C-Kapselung & Schichtung:</strong></li>\n<li>Strenges Einhalten des Schichtenprinzips: Assistenz-SWCs (<code>CrsCtrlAndAcc</code>) dürfen keine direkten Aktuatorports (<code>Esc</code>, <code>Power-Train</code>, <code>Epb</code>) bedienen; sämtliche Eingriffe müssen über Koordinatoren (<code>Vlc</code>, <code>Ssm</code>) arbitriert werden.</li>\n<li>Zeitkritische Pfade (<code>Vlc</code> $\\leftrightarrow$ <code>Esc</code> $\\leftrightarrow$ <code>Power-Train</code>) erfordern RTE-Task-Perioden $\\le 10\\,\\text{ms}$ mit synchronem Lese-/Schreibzugriff (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) zur Vermeidung von Jitter und Semaphore-Blocking.</li>\n<li><strong>Port-Definition & Standard-Datentypen:</strong></li>\n<li>Verwendung der genormten AUTOSAR-Application-Interface-Datentypen (z. B. Beschleunigungen in $\\text{m/s}^2$, Momente in $\\text{Nm}$, Drehzahlen in $1/\\text{min}$ nach standardisierten <code>CompuMethods</code>).</li>\n<li>Signal-Statusflags müssen Signalqualitäten (<code>Valid</code>, <code>Invalid</code>, <code>Degraded</code>) mitführen, um deterministische Rückfallebenen bei Sensorausfall abzusichern.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Kernkomponenten (<code>Vlc</code>, <code>Esc</code>, <code>Steer</code>, <code>Ssm</code>) sind typischerweise bis ASIL D eingestuft.</li>\n<li>Der Kommunikationspfad zwischen den ECUs/Partitionen erfordert E2E-Absicherung (CRC, Sequence Counter, Alive Supervision via E2E-Protection-Wrapper).</li>\n<li>Plausibilisierungs- und Degradationsgatter in <code>Vlc</code> und <code>Esc</code> sind obligatorisch, um ungewollte Beschleunigungs- oder Bremsanforderungen (z. B. durch Single-Point-Faults in ACC oder Umfeldsensorik) sicher abzufangen.</li>\n</ul>"}, {"id": "FIG-9e03353a5a9dfaf6", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Funktions- und Domänen-Architekturdiagramm (Software Composition & Component Interaction Overview) auf Ebene der AUTOSAR-Applikationsschicht (Application Layer / VFB-Ebene).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert die modulare Dekomposition der AUTOSAR-Chassis-Domäne gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3).</li>\n<li>Definiert die hierarchischen Signal- und Kontrollbeziehungen zwischen Umfeld-/Fahrzeugsensorik, High-Level-Assistenz- und Regelfunktionen (ACC, VLC, SSM), Querstabilisierungs-SWCs und den Basis-Aktuatorsystemen.</li>\n<li>Markiert die Domänengrenze zur Antriebs-Domäne (<code>Power-Train</code>, grau hinterlegt als externes Subsystem), welche die Längskraft-Schnittstelle bedient.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Sensor-Ebene (Perzeptionsschicht)</p>\n<ul class=\"fig-list\">\n<li><strong><code>SurrndgsSnsr</code> (Surroundings Sensor):</strong> Sensor-SWC/Composition für Umfeldsensorik (Radar, Lidar, Kamera) zur Erfassung von Objektabständen, Relativgeschwindigkeiten und Spurgeometrien.</li>\n<li><strong><code>ChassisSnsr</code> (Chassis Sensor):</strong> Sensor-SWC/Composition für fahrzeugeigene Fahrdynamikgrößen (Raddrehzahlen, Gierrate, Quer-/Längsbeschleunigung, Lenkwinkel).</li>\n</ul>\n<p class=\"fig-p\">#### Koordinations- & Reglerebene (High-Level Control)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> (Cruise Control & Adaptive Cruise Control):</strong> Berechnet aus Fahrerwunsch und Umfelddaten longitudinale Soll-Bewegungsgrößen ($v_{set}$, $a_{req}$).</li>\n<li><strong><code>Vlc</code> (Vehicle Longitudinal Control):</strong> Zentraler Längsdynamikkoordinator. Arbitriert Beschleunigungsanforderungen (Fahrerpedal, ACC, Limiter) und verteilt Sollmomente an Vortrieb (<code>Power-Train</code>) und Verzögerung (<code>Esc</code>).</li>\n<li><strong><code>Ssm</code> (Standstill Management):</strong> Zustandsmanager für Fahrzeugstillstand (Hill-Hold, Stop&Go, Schnittstelle hydraulischer Halt $\\leftrightarrow$ elektromechanische Verriegelung).</li>\n<li><strong><code>Rsc</code> (Roll Stability Control):</strong> Kipp- und Wankstabilitätsüberwachung; fordert stabilisierende Radbremsungen bei <code>Esc</code> an.</li>\n<li><strong><code>SteerVehStabyCtrl</code> (Steering Vehicle Stability Control):</strong> Fahrdynamische Lenkungsstabilisierung (z. B. Übersteuer-/Untersteuer-Korrektur, Gegenlenkempfehlung / DSR).</li>\n<li><strong><code>SteerDrvrAsscSys</code> (Steering Driver Assistance System):</strong> Komfort- und Spurführungsassistenten (LKA, Parklenkassistent).</li>\n</ul>\n<p class=\"fig-p\">#### Aktuator- & Basisebene (Low-Level Execution & Subsysteme)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power-Train</code> (Powertrain, grau):</strong> Externe Domäne für Bereitstellung und Modulation des Antriebsmoments.</li>\n<li><strong><code>TirePMon</code> (Tire Pressure Monitoring):</strong> Reifendrucküberwachung (direkt/indirekt).</li>\n<li><strong><code>Epb</code> (Electric Parking Brake):</strong> Elektromechanischer Feststellbremsaktuator.</li>\n<li><strong><code>Esc</code> (Electronic Stability Control):</strong> Bremssystemregler (ABS, ASR, ESP, aktiver hydraulischer Bremsdruckaufbau).</li>\n<li><strong><code>Steer</code> (Steering):</strong> Lenksystem-Basisansteuerung (EPS / Überlagerungslenkung).</li>\n<li><strong><code>Susp</code> (Suspension):</strong> Vertikaldynamikregelung (adaptive Dämpfung, Niveauregulierung).</li>\n<li><strong><code>DtTqDistbn</code> (Drivetrain Torque Distribution):</strong> Drehmomentverteilung (Allrad-Längs-/Quersperren, Torque Vectoring).</li>\n<li><strong><code>PrkgAid</code> (Parking Aid):</strong> Parkassistenz-Subsystem zur Unterstützung bei Rangiervorgängen und Parkmanövern.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc</code> $\\leftrightarrow$ <code>Vlc</code>:</strong> Bidirektionales Sender-Receiver-Interface (<code>AccelReq</code>, Status/Availability).</li>\n<li><strong><code>Vlc</code> $\\rightarrow$ <code>Power-Train</code>:</strong> Unidirektionaler Befehlspfad für positives Drehmoment/Beschleunigung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Bidirektionaler Pfad für Bremsverzögerungsanforderung und Status/Grenzmoment-Rückmeldung.</li>\n<li><strong><code>Vlc</code> $\\leftrightarrow$ <code>Ssm</code> $\\leftrightarrow$ <code>Epb</code> / <code>Esc</code>:</strong> Stillstandskoordination (Anforderung Haltezustand an <code>Ssm</code>, hydraulische Bremsdruckhaltung via <code>Esc</code>, Übergang zur mechanischen Verriegelung via <code>Epb</code>).</li>\n<li><strong><code>Rsc</code> $\\leftrightarrow$ <code>Esc</code>:</strong> Vertikaler Stabilisierungspfad (Kippgefahr-Erkennung und Bremseingriffsanforderung).</li>\n<li><strong><code>SteerVehStabyCtrl</code> / <code>SteerDrvrAsscSys</code> $\\rightarrow$ <code>Steer</code>:</strong> Unidirektionale Ansteuerpfade für fahrdynamische bzw. assistierende Überlagerungslenkeingriffe.</li>\n<li><strong><code>Esc</code> $\\rightarrow$ <code>CrsCtrlAndAcc</code>, <code>Vlc</code>, <code>SteerVehStabyCtrl</code>, <code>SteerDrvrAsscSys</code>:</strong> Bereitstellung von Raddrehzahlen und Fahrzeugbewegungszuständen über Abzweigknoten.</li>\n<li><strong>Untere Verteilleitung (von <code>Esc</code>):</strong> Verteilung zentraler Raddynamikgrößen an <code>TirePMon</code>, <code>Epb</code>, <code>Steer</code>, <code>Susp</code>, <code>DtTqDistbn</code> sowie die neu angebundene Komponente <code>PrkgAid</code> und Kopplungspfad zu <code>Power-Train</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamische Wirkkette:</strong> Fahrer- oder ACC-Vorgaben werden in <code>CrsCtrlAndAcc</code> generiert und an <code>Vlc</code> übermittelt. <code>Vlc</code> führt die Priorisierung/Arbitrierung durch und adressiert bei Beschleunigungsbedarf das externe <code>Power-Train</code>-System, bei Verzögerungsbedarf das <code>Esc</code>. Im Stillstandsfall übernimmt <code>Ssm</code> die Kaskadierung vom hydraulischen Halten (<code>Esc</code>) zum dauerhaften Feststellen (<code>Epb</code>).</li>\n<li><strong>Querdynamische Wirkkette:</strong> <code>SteerVehStabyCtrl</code> (stabilitätsrelevant) und <code>SteerDrvrAsscSys</code> (komfortrelevant) senden unabhängige Überlagerungs- bzw. Lenkmomentanforderungen an das Basislenksystem <code>Steer</code>. Bei kritischen Wankbewegungen triggert <code>Rsc</code> autonome Stabilisierungsbremsungen über <code>Esc</code>.</li>\n<li><strong>Zustands- und Datenrückkopplung:</strong> <code>Esc</code> fungiert als primärer Sensor-/Fahrdynamik-Hub, der gemessene Radgeschwindigkeiten und Bewegungsgrößen sowohl an die High-Level-Funktionen (<code>CrsCtrlAndAcc</code>, <code>Vlc</code>, Lenkregler) als auch über die untere Verteilleitung an periphere Subsysteme (<code>TirePMon</code>, <code>Susp</code>, <code>DtTqDistbn</code>, <code>Steer</code>, <code>Epb</code> sowie <code>PrkgAid</code> für Wegstrecken-/Richtungserfassung) rückspeist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C-Kapselung & Schichtung:</strong></li>\n<li>Strenges Einhalten des Schichtenprinzips: Assistenz-SWCs (<code>CrsCtrlAndAcc</code>) dürfen keine direkten Aktuatorports (<code>Esc</code>, <code>Power-Train</code>, <code>Epb</code>) bedienen; sämtliche Eingriffe müssen über Koordinatoren (<code>Vlc</code>, <code>Ssm</code>) arbitriert werden.</li>\n<li>Zeitkritische Pfade (<code>Vlc</code> $\\leftrightarrow$ <code>Esc</code> $\\leftrightarrow$ <code>Power-Train</code>) erfordern RTE-Task-Perioden $\\le 10\\,\\text{ms}$ mit synchronem Lese-/Schreibzugriff (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) zur Vermeidung von Jitter und Semaphore-Blocking.</li>\n<li><strong>Port-Definition & Standard-Datentypen:</strong></li>\n<li>Verwendung der genormten AUTOSAR-Application-Interface-Datentypen (z. B. Beschleunigungen in $\\text{m/s}^2$, Momente in $\\text{Nm}$, Drehzahlen in $1/\\text{min}$ nach standardisierten <code>CompuMethods</code>).</li>\n<li>Signal-Statusflags müssen Signalqualitäten (<code>Valid</code>, <code>Invalid</code>, <code>Degraded</code>) mitführen, um deterministische Rückfallebenen bei Sensorausfall abzusichern.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Kernkomponenten (<code>Vlc</code>, <code>Esc</code>, <code>Steer</code>, <code>Ssm</code>) sind typischerweise bis ASIL D eingestuft.</li>\n<li>Der Kommunikationspfad zwischen den ECUs/Partitionen erfordert E2E-Absicherung (CRC, Sequence Counter, Alive Supervision via E2E-Protection-Wrapper).</li>\n<li>Plausibilisierungs- und Degradationsgatter in <code>Vlc</code> und <code>Esc</code> sind obligatorisch, um ungewollte Beschleunigungs- oder Bremsanforderungen (z. B. durch Single-Point-Faults in ACC oder Umfeldsensorik) sicher abzufangen.</li>\n</ul>"}], "trans": [{"from": "FIG-40c06d4071119f34", "to": "FIG-92922157b4aef669", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DtTqDibtn</code>: Umbenannt zu <code>DtTqDistbn</code>.</li>\n<li><code>PrkgAid</code>: Neue Subsystem-Komponente (Parking Aid) in der unteren Ebene rechts von <code>DtTqDistbn</code> ergänzt.</li>\n<li>Schnittstelle <code>Esc</code> $\\rightarrow$ <code>PrkgAid</code>: Untere Verteilleitung (Fahrzeug-/Raddynamikdaten) von <code>Esc</code> um eine Abzweigung mit Pfeil auf <code>PrkgAid</code> erweitert.</li>\n</ul>"}, {"from": "FIG-92922157b4aef669", "to": "FIG-18cf62325dc5cccf", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-18cf62325dc5cccf", "to": "FIG-9e03353a5a9dfaf6", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
